          "quote": "early-termination fee of fifty dollars"
        }
      ],
      "label": "billing",
      "confidence": 0.8,
      "rationale": "Billing becomes a secondary issue when the early-termination fee is disclosed and disputed."
    }
  ],
  "resolution": {
    "evidence": [
      {
